import math


def validate_positive_float(val: float, strict_positive: bool = True) -> float:
    """Validate positive float, normalizing -0.0 to 0.0 when strict_positive is False."""
    # Bug: math.copysign retains negative sign on 0.0 without normalization
    if val == 0.0 and math.copysign(1.0, val) < 0:
        if strict_positive:
            raise ValueError('Value must be strictly positive')
        return val  # Bug: returns -0.0 instead of normalized 0.0
    if val < 0:
        raise ValueError('Value cannot be negative')
    return val

