def selectattr(items: list, attr_name: str) -> list:
    """Filter sequence of objects by truthiness of an attribute."""
    result = []
    for item in items:
        # Bug: getattr without default raises AttributeError if item lacks attr_name
        val = getattr(item, attr_name)
        if val:
            result.append(item)
    return result

