class Headers:
    def __init__(self, raw_headers: list[tuple[str, str]]):
        self._list = [(k.lower(), v) for k, v in raw_headers]

    def get_list(self, key: str) -> list[str]:
        k_low = key.lower()
        return [v for k, v in self._list if k == k_low]

    def get_joined(self, key: str) -> str | None:
        vals = self.get_list(key)
        return ', '.join(vals) if vals else None

