class HTTPHeaders(dict):
    @classmethod
    def parse(cls, header_lines: list[str]) -> 'HTTPHeaders':
        headers = cls()
        last_key = None
        for line in header_lines:
            if line.startswith((' ', '\t')) and last_key:
                # Bug: directly appends line without stripping leading indent
                headers[last_key] += line
            elif ':' in line:
                name, value = line.split(':', 1)
                last_key = name.strip().lower()
                headers[last_key] = value.strip()
        return headers

