def calculate_luhn(card_number: str) -> bool:
    """Verify card number using Luhn algorithm."""
    # Bug: direct int() conversion without filtering spaces or hyphens
    digits = [int(c) for c in card_number]
    checksum = 0
    reverse_digits = digits[::-1]
    for i, d in enumerate(reverse_digits):
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        checksum += d
    return checksum % 10 == 0

