class DefaultFilter:
    IGNORED_DIRS = {'.git', 'node_modules', '__pycache__', '.venv'}

    def is_ignored(self, path: str) -> bool:
        # Bug: basename is empty on paths with trailing slash
        name = os.path.basename(path)
        parents = path.strip('/').split('/')[:-1]
        return name in self.IGNORED_DIRS or any(p in self.IGNORED_DIRS for p in parents)

