def scan_fstring(text: str) -> list[str]:
    """Scan f-string into literal and expression segments."""
    tokens = []
    i = 0
    n = len(text)
    # Bug: does not check for double braces '{{' or '}}' as escaped literals
    while i < n:
        if text[i] == '{':
            end = text.find('}', i)
            if end == -1:
                raise ValueError('Unclosed f-string expression')
            tokens.append(f'EXPR:{text[i+1:end]}')
            i = end + 1
        else:
            tokens.append(f'LIT:{text[i]}')
            i += 1
    return tokens

